function exportPreferencesSection(interfaceSettingsDataSection, asFile = true, initial_value = false) {
  const section = {};
  for (let key in interfaceSettingsDataSection) {
    for (let subkey in interfaceSettingsDataSection[key]) {
      if (interfaceSettingsDataSection[key][subkey].id) {
        if (interfaceSettingsDataSection[key][subkey].type == "group") {
          interfaceSettingsDataSection[key][subkey].value.forEach(element => {
            section[element.id] = asFile ? element.initial : element.value;
          });
        } else if (interfaceSettingsDataSection[key][subkey].type == "list") {
          const itemsList = [];
          interfaceSettingsDataSection[key][subkey].value.forEach(element => {
            const item = {};
            item.id = element.id;
            element.value.forEach(setting => {
              item[setting.name] = asFile ? setting.initial : setting.value;
            });
            itemsList.push(item);
          });
          section[interfaceSettingsDataSection[key][subkey].id] = itemsList;
        } else {
          section[interfaceSettingsDataSection[key][subkey].id] = asFile || initial_value ? interfaceSettingsDataSection[key][subkey].initial : interfaceSettingsDataSection[key][subkey].value;
        }
      }
    }
  }
  return section;
}
function exportPreferences(interfaceSettingsData, asFile = true) {
  console.log("exportPreferences for");
  console.log(JSON.parse(JSON.stringify(interfaceSettingsData)));
  const preferences = {};
  const filename = "preferences.json";
  preferences.settings = {};
  if (interfaceSettingsData.custom) preferences.custom = interfaceSettingsData.custom;
  if (interfaceSettingsData.extensions) preferences.extensions = interfaceSettingsData.extensions;
  preferences.settings = exportPreferencesSection(interfaceSettingsData.settings, asFile);
  if (asFile) {
    const file = new Blob([JSON.stringify(preferences, null, " ")], {
      type: "application/json"
    });
    if (window.navigator.msSaveOrOpenBlob)
      // IE10+
      window.navigator.msSaveOrOpenBlob(file, filename);else {
      // Others
      const a = document.createElement("a");
      const url = URL.createObjectURL(file);
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      setTimeout(function () {
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
      }, 0);
    }
  }
  console.log("exportPreferences done");
  console.log(preferences);
  return preferences;
}


